import sqlite3

p = "./abb-tablegpt-0bueqplp/profile/history.sqlite"
con = sqlite3.connect(p)

for (t,) in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall():
    cols = [d[0] for d in con.execute(f"SELECT * FROM {t} LIMIT 1").description]
    n = con.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
    print(f"table={t} rows={n} cols={cols}")
    # where did 'epoch' / 'quorum' / 'inject' actually come from?
    for c in cols:
        try:
            hit = con.execute(
                f"SELECT COUNT(*) FROM {t} WHERE CAST({c} AS TEXT) LIKE '%quorum%' "
                f"OR CAST({c} AS TEXT) LIKE '%apply_index%'"
            ).fetchone()[0]
            if hit:
                print(f"   column '{c}' contains {hit} rows matching quorum/apply_index")
        except Exception:
            pass

